func (r *runtime) current() *environment { return r.environments[len(r.environments)-1] }
func (r *runtime) assign(name string, value int64) {
	for i := len(r.environments) - 1; i > 0; i-- {
		if _, exists := r.environments[i].variables[name]; exists {
			r.environments[i].variables[name] = value
			return
		}
	}
	r.environments[0].variables[name] = value
}
func (r *runtime) evaluate(e *expression) int64 {
	t := e.token
	if e.kind == "variable" {
		for i := len(r.environments) - 1; i >= 0; i-- {
			if value, exists := r.environments[i].variables[t.name]; exists {
				return value
			}
		}
func (r *runtime) call(t token, values []int64) *int64 {
	procedure := r.procedures[t.text]
	environment := &environment{variables: map[string]int64{}}
	for i, name := range procedure.parameters {
		environment.variables[name] = values[i]
	}
	r.environments = append(r.environments, environment)
	r.calls = append(r.calls, procedure.name)
	signal := r.sequence(procedure.body)
	r.environments = r.environments[:len(r.environments)-1]
	r.calls = r.calls[:len(r.calls)-1]
	if signal != nil && signal.output {
		value := signal.value
		return &value
	}
	return nil
func (r *runtime) sequence(commands []*command) *control {
	for _, command := range commands {
		if signal := r.execute(command); signal != nil {
			return signal
		}
	}
	return nil
}
func (r *runtime) execute(c *command) *control {
	if c.kind == "WHILE" {
		for r.evaluate(c.inputs[0].expression) != 0 {
			if signal := r.sequence(c.inputs[1].list); signal != nil {
				return signal
			}
		}
		return nil
	}
	values := make([]int64, len(c.inputs))
	for i, item := range c.inputs {
		if item.expression != nil {
			values[i] = r.evaluate(item.expression)
		}
	}
	t := c.token
	if c.kind == "procedure" {
		if value := r.call(t, values); value != nil {
	switch c.kind {
	case "OUTPUT":
		return &control{output: true, value: values[0]}
	case "MAKE":
		r.assign(c.inputs[0].quoted.name, values[1])
	case "LOCAL":
		r.current().variables[c.inputs[0].quoted.name] = 0
	case "LOCALMAKE":
		r.current().variables[c.inputs[0].quoted.name] = values[1]
